#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> g(n, vector<long long>(m));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            cin >> g[i][j];
        }
    }

    vector<long long> rowSum(n, 0), colSum(m, 0);
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            rowSum[i] += g[i][j];
            colSum[j] += g[i][j];
        }
    }
    for (int i = 0; i < n; i++) cout << rowSum[i] << (i + 1 < n ? " " : "\n");
    for (int j = 0; j < m; j++) cout << colSum[j] << (j + 1 < m ? " " : "\n");

    return 0;
}

